#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> pii;
char grid1[15][15], grid2[15][15];
int directions[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int index_map[65][15][15];
int capacity[15][15];
int counter = 1;

struct Edge {
  int u, v;
  long long cap, flow;
  Edge() {}
  Edge(int u, int v, long long cap): u(u), v(v), cap(cap), flow(0) {}
};

struct MaxFlowSolver {
  int nodeCount;
  vector<Edge> edges;
  vector<vector<int>> graph;
  vector<int> dist, ptr;

  MaxFlowSolver(int N): nodeCount(N), edges(0), graph(N), dist(N), ptr(N) {}

  void addEdge(int u, int v, long long cap) {
    if (u != v) {
      edges.emplace_back(Edge(u, v, cap));
      graph[u].push_back(edges.size() - 1);
      edges.emplace_back(Edge(v, u, 0));
      graph[v].push_back(edges.size() - 1);
    }
  }

  bool buildLevelGraph(int S, int T) {
    queue<int> q({S});
    fill(dist.begin(), dist.end(), nodeCount + 1);
    dist[S] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      if (u == T) break;
      for (int k: graph[u]) {
        Edge &e = edges[k];
        if (e.flow < e.cap && dist[e.v] > dist[e.u] + 1) {
          dist[e.v] = dist[e.u] + 1;
          q.emplace(e.v);
        }
      }
    }
    return dist[T] != nodeCount + 1;
  }

  long long sendFlow(int u, int T, long long flow = -1) {
    if (u == T || flow == 0) return flow;
    for (int &i = ptr[u]; i < (int)graph[u].size(); ++i) {
      Edge &e = edges[graph[u][i]];
      Edge &oe = edges[graph[u][i]^1];
      if (dist[e.v] == dist[e.u] + 1) {
        long long amt = e.cap - e.flow;
        if (flow != -1 && amt > flow) amt = flow;
        long long pushed = sendFlow(e.v, T, amt);
        if (pushed > 0) {
          e.flow += pushed;
          oe.flow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  long long computeMaxFlow(int S, int T) {
    long long totalFlow = 0;
    while (buildLevelGraph(S, T)) {
      fill(ptr.begin(), ptr.end(), 0);
      while (long long flow = sendFlow(S, T))
        totalFlow += flow;
    }
    return totalFlow;
  }
};

int main() {
  memset(capacity, -1, sizeof(capacity));
  int n, t;
  scanf("%d%d", &n, &t);
  for (int i=1; i<=n; i++) {
    scanf("%s", grid1[i]+1);
  }
  for (int i=0; i<=t+1; i++) {
    for (int j=1; j<=n; j++) {
      for (int k=1; k<=n; k++) {
        index_map[i][j][k] = counter++;
      }
    }
  }
  counter++;
  for (int i=1; i<=n; i++) {
    scanf("%s", grid2[i]+1);
  }
  queue<pii> q;
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (grid1[i][j] == 'Z') {
        q.push({i, j});
        capacity[i][j] = 0;
      }
    }
  }
  while (!q.empty()) {
    int y = q.front().first, x = q.front().second;
    q.pop();
    for (int i=0; i<4; i++) {
      int ny = y + directions[i][0], nx = x + directions[i][1];
      if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && grid1[ny][nx] != 'Y' && capacity[ny][nx] == -1) {
        capacity[ny][nx] = capacity[y][x] + 1;
        q.push({ny, nx});
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (capacity[i][j] == -1) capacity[i][j] = 1e9;
      if (capacity[i][j] > t) capacity[i][j] = 1e9;
    }
  }
  int source = 0, sink = counter - 1;
  MaxFlowSolver mf(counter);
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
        mf.addEdge(source, index_map[0][i][j], grid1[i][j]-'0');
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
      for (int k=0; k<4; k++) {
        int ny = i + directions[k][0], nx = j + directions[k][1];
        if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && grid1[ny][nx] != 'Y' && grid1[ny][nx] != 'Z') {
          for (int x=0; x<t; x++) {
            if (capacity[ny][nx] >= x+1 && capacity[i][j] > x) {
              mf.addEdge(index_map[x][i][j], index_map[x+1][ny][nx], 1000);
            }
          }
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
      for (int x=0; x<=t; x++) {
        if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
          mf.addEdge(index_map[x][i][j], index_map[t+1][i][j], grid2[i][j]-'0');
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
      if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
        mf.addEdge(index_map[t+1][i][j], sink, grid2[i][j]-'0');
      }
    }
  }
  printf("%lld\n", mf.computeMaxFlow(source, sink));
}
